        object converted = type == typeof(string) ? HkValue.Canon(value) ?? ""
            : type == typeof(DateOnly) ? DateOnly.FromDateTime(value is string s ? DateTime.Parse(s, CultureInfo.InvariantCulture) : Convert.ToDateTime(value, CultureInfo.InvariantCulture))
