            : type == typeof(bool) ? HkCondition.IsTrue(value)
            : type == typeof(DateTime) && value is string text ? DateTime.Parse(text, CultureInfo.InvariantCulture)
            : Convert.ChangeType(value, type, CultureInfo.InvariantCulture);
        return (T)converted;
    }
}

