        if (string.IsNullOrWhiteSpace(cs))
        {
            throw new InvalidOperationException(
                "No connection string. Store it outside the project, for example: dotnet user-secrets set ConnectionStrings:Hokusai \"<connection string>\" " +
                "or set the environment variable ConnectionStrings__Hokusai.");
