        return new HokusaiOptions
        {
            Provider = Enum.TryParse<ProviderKind>(configuration["Hokusai:Provider"], ignoreCase: true, out var p) ? p : defaultProvider,
            ConnectionString = cs,
            EnableUnverified = string.Equals(configuration["Hokusai:EnableUnverified"], "true", StringComparison.OrdinalIgnoreCase),
