/// <summary>Refuses to target a database on another machine unless that was configured explicitly.</summary>
public static class DatabaseGuard
{
    public static void EnsureAllowed(HokusaiOptions options)
    {
        if (options.AllowNonLocalDatabase || IsLocal(options.Provider, options.ConnectionString))
        {
            return;
        }

        throw new InvalidOperationException(
            "The connection string points at a database that is not on this machine. Set Hokusai:AllowNonLocalDatabase=true to allow it, " +
            "and use a least-privilege login (read-only for read actions).");
    }

    public static bool IsLocal(ProviderKind provider, string connectionString)
    {
        switch (provider)
        {
            case ProviderKind.SqlServer:
                var source = new SqlConnectionStringBuilder(connectionString).DataSource.Trim().ToUpperInvariant();
                if (source.StartsWith("TCP:", StringComparison.Ordinal) || source.StartsWith("NP:", StringComparison.Ordinal) || source.StartsWith("LPC:", StringComparison.Ordinal))
                {
                    source = source[(source.IndexOf(':', StringComparison.Ordinal) + 1)..];
                }

                if (source.StartsWith("(LOCALDB)", StringComparison.Ordinal) || source.StartsWith(@"\\.\PIPE", StringComparison.Ordinal))
                {
                    return true;
                }

                var host = source.Split('\\', ',')[0];
                return host is "." or "(LOCAL)" or "LOCALHOST" or "127.0.0.1" or "::1" || host == Environment.MachineName.ToUpperInvariant();
            case ProviderKind.Sqlite:
                return IsLocalPath(new SqliteConnectionStringBuilder(connectionString).DataSource);
            default:
                var builder = new DbConnectionStringBuilder { ConnectionString = connectionString };
                foreach (var key in new[] { "Data Source", "Database", "DBQ" })
                {
                    if (builder.TryGetValue(key, out var value) && value is string path && path.Length > 0)
                    {
                        return IsLocalPath(path);
                    }
                }

                return false;
        }
    }

    private static bool IsLocalPath(string path) => !path.StartsWith(@"\\", StringComparison.Ordinal) && !path.Contains("://", StringComparison.Ordinal);
}

/// <summary>Compares the schema of every table an action touches with the schema it was inferred from.</summary>
public static class SchemaGuard
{
    public static async Task<List<string>> CheckAsync(HokusaiOptions options, IEnumerable<ActionInfo> actions, CancellationToken ct)
    {
        await using var connection = await HkDb.OpenAsync(options.Provider, options.ConnectionString, ct);
        var schema = await SchemaReader.ReadAsync(connection, options.Provider, ct);
        // Disabled actions never run, so their tables do not hold the API back.
        return [.. actions.Where(a => (a.Verified || options.EnableUnverified) && schema.Fingerprint(a.Tables) != a.Fingerprint).Select(a => a.Name)];
    }

    /// <summary>Throws when any action's tables changed: serving it could write data the app would not.</summary>
    public static async Task EnsureAsync(HokusaiOptions options, IEnumerable<ActionInfo> actions, CancellationToken ct)
    {
        var drifted = await CheckAsync(options, actions, ct);
        if (drifted.Count > 0)
        {
            throw new InvalidOperationException(
                $"Schema drift detected for: {string.Join(", ", drifted)}. The tables changed since these actions were inferred; re-run 'hokusai infer', 'verify' and 'generate'.");
        }
    }
}

/// <summary>Validates inputs and runs an action in a transaction, or plans it for a dry run.</summary>
public sealed class ActionRunner(HokusaiOptions options)
{
    public async Task<ActionResponse> RunAsync<TInput>(
        ActionInfo info,
        TInput input,
        Func<TInput, List<string>> validate,
        Func<DbConnection?, DbTransaction?, ProviderKind, TInput, bool, CancellationToken, Task<ActionOutcome>> execute,
        bool dryRun,
        CancellationToken ct)
    {
        if (!info.Verified && !options.EnableUnverified)
        {
            throw new ActionDisabledException($"'{info.DisplayName}' is disabled: {info.DisabledReason ?? "it was not verified"}.");
        }

        var errors = validate(input);
        if (errors.Count > 0)
        {
            throw new ActionValidationException(errors);
        }

        if (dryRun)
        {
            var planned = await execute(null, null, options.Provider, input, true, ct);
            return new ActionResponse { Action = info.Name, DryRun = true, Statements = planned.Plan };
        }

        await using var connection = await HkDb.OpenAsync(options.Provider, options.ConnectionString, ct);
        await using var transaction = await connection.BeginTransactionAsync(ct);
        try
        {
            var outcome = await execute(connection, transaction, options.Provider, input, false, ct);
            await transaction.CommitAsync(ct);
            return new ActionResponse { Action = info.Name, RowsAffected = outcome.RowsAffected, Rows = outcome.Rows, File = outcome.File };
        }
        catch (HkInputException ex)
        {
            await transaction.RollbackAsync(CancellationToken.None);
            throw new ActionValidationException([ex.Message]);
        }
        catch
        {
            await transaction.RollbackAsync(CancellationToken.None);
            throw;
        }
    }
}
